  1	import java.util.ArrayList;
  2	import java.util.Iterator;
  3	import java.util.List;
  4	
  5	/**
  6	 * A simple predator-prey simulator, based on a rectangular field
  7	 * containing lions, zebras, and other organisms.
  8	 *
  9	 * @version 2022.03.02
 10	 */
 11	public class Simulator
 12	{
 13	    // Default grid dimensions.
 14	    private static final int DEFAULT_WIDTH = 200;
 15	    private static final int DEFAULT_DEPTH = 200;
 16	
 17	    // Simulation time constants.
 18	    private static final int STEPS_PER_HOUR   = 5;
 19	    private static final int HOURS_PER_DAY    = 24;
 20	    private static final int HOURS_PER_PERIOD = 4;   // how often TimeOfDay advances
 21	
 22	    // All organisms currently in the simulation.
 23	    private List<Organism> organisms;
 24	    // The grid.
 25	    private Field field;
 26	    // Current step count.
 27	    private int step;
 28	    // The GUI.
 29	    private SimulatorView view;
 30	    // Current hour within the day (1-based).
 31	    private int hour;
 32	    // Current time-of-day period.
 33	    private TimeOfDay currentTime;
 34	    // Current weather.
 35	    private Weather currentWeather;
 36	
 37	    /**
 38	     * Construct a simulation field with default size.
 39	     */
 40	    public Simulator()
 41	    {
 42	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
 43	    }
 44	
 45	    /**
 46	     * Create a simulation field with the given size.
 47	     * @param depth Depth of the field. Must be greater than zero.
 48	     * @param width Width of the field. Must be greater than zero.
 49	     */
 50	    public Simulator(int depth, int width)
 51	    {
 52	        if(width <= 0 || depth <= 0) {
 53	            System.out.println("The dimensions must be greater than zero.");
 54	            System.out.println("Using default values.");
 55	            depth = DEFAULT_DEPTH;
 56	            width = DEFAULT_WIDTH;
 57	        }
 58	
 59	        organisms = new ArrayList<>();
 60	        field     = new Field(depth, width);
 61	        view      = new SimulatorView(depth, width);
 62	
 63	        reset();
 64	    }
 65	
 66	    /**
 67	     * Run the simulation from its current state for a reasonably long period
 68	     * (4000 steps).
 69	     */
 70	    public void runLongSimulation()
 71	    {
 72	        simulate(4000);
 73	    }
 74	
 75	    /**
 76	     * Run the simulation from its current state for the given number of steps.
 77	     * Stops early if the simulation ceases to be viable.
 78	     * @param numSteps The number of steps to run for.
 79	     */
 80	    public void simulate(int numSteps)
 81	    {
 82	        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
 83	            simulateOneStep();
 84	            delay(5);
 85	        }
 86	    }
 87	
 88	    /**
 89	     * Run the simulation from its current state for a single step.
 90	     * Each organism acts, newborns are collected, then environment is updated.
 91	     */
 92	    public void simulateOneStep()
 93	    {
 94	        step++;
 95	
 96	        List<Organism> newOrganisms = new ArrayList<>();
 97	        for(Iterator<Organism> it = organisms.iterator(); it.hasNext(); ) {
 98	            Organism organism = it.next();
 99	            organism.act(newOrganisms, currentWeather, currentTime);
100	            if(organism.isRemoved()) {
101	                it.remove();
102	            }
103	        }
104	        organisms.addAll(newOrganisms);
105	
106	        int day = step / (STEPS_PER_HOUR * HOURS_PER_DAY) + 1;
107	        hour = (step / STEPS_PER_HOUR) % HOURS_PER_DAY + 1;
108	
109	        view.showStatus(step, field);
110	        view.updateTimeLabel(day, hour);
111	        view.updateEnvironmentLabel(currentWeather, currentTime);
112	
113	        if(step % STEPS_PER_HOUR == 0) {
114	            currentWeather.generate();
115	        }
116	
117	        if(hour % HOURS_PER_PERIOD == 0 && step % STEPS_PER_HOUR == 0) {
118	            currentTime = currentTime.next();
119	        }
120	    }
121	
122	    public int getHour() { return hour; }
123	
124	    /**
125	     * Reset the simulation to a starting position.
126	     */
127	    public void reset()
128	    {
129	        step = 0;
130	        currentTime    = TimeOfDay.SUNRISE;
131	        currentWeather = new Weather(WeatherType.SUN);
132	
133	        organisms.clear();
134	
135	        Populator populator = new Populator(view);
136	        populator.populate(organisms, field);
137	
138	        view.showStatus(step, field);
139	    }
140	
141	    /**
142	     * Pause for a given time.
143	     * @param millisec The time to pause for, in milliseconds.
144	     */
145	    private void delay(int millisec)
146	    {
147	        try {
148	            Thread.sleep(millisec);
149	        }
150	        catch(InterruptedException ie) {
151	            // wake up
152	        }
153	    }
154	}

