  1	import java.util.List;
  2	import java.util.Random;
  3	
  4	/**
  5	 * This file is part of the Predator-Prey Simulation.
  6	 *
  7	 * An abstract class representing any organism in the simulation.
  8	 *
  9	 * @version 2022.03.02
 10	 */
 11	public abstract class Organism implements Entity {
 12	
 13	    // steps a dead body lingers on the field before auto-removal
 14	    private static final int LIFETIME_AFTER_DEATH = 40;
 15	    private boolean alive;
 16	    private boolean removed;
 17	    private Field field;
 18	    private Location location;
 19	    private int howLongDead;
 20	
 21	    private int age;
 22	
 23	    // shared random generator to generate consistent results
 24	    private static final Random rand = Randomizer.getRandom();
 25	
 26	    /**
 27	     * Constructor for an Organism in the simulation.
 28	     *
 29	     * @param randomAge Whether we assign this organism a random age or not.
 30	     * @param field The field in which this organism resides.
 31	     * @param location The location in which this organism is spawned into.
 32	     */
 33	    public Organism(boolean randomAge, Field field, Location location) {
 34	        alive = true;
 35	        this.field = field;
 36	        setLocation(location);
 37	
 38	        if (randomAge) {
 39	            age = rand.nextInt(getMaxAge());
 40	        } else {
 41	            age = 0;
 42	        }
 43	    }
 44	
 45	    /**
 46	     * Abstract method for what an organism does, i.e. what is always run at every step.
 47	     *
 48	     * @param newOrganisms A list of all newborn organisms in this simulation step.
 49	     * @param weather The current state of weather in the simulation.
 50	     * @param time The current state of time in the simulation.
 51	     */
 52	    @Override
 53	    abstract public void act(List<Organism> newOrganisms, Weather weather, TimeOfDay time);
 54	
 55	    /**
 56	     * Check whether the organism is alive or not.
 57	     * @return true if the organism is still alive.
 58	     */
 59	    protected boolean isAlive()
 60	    {
 61	        return alive;
 62	    }
 63	
 64	    /**
 65	     * Removes the current organism from the field.
 66	     */
 67	    protected void remove() {
 68	        setDead();
 69	        removeFromField();
 70	        removed = true;
 71	    }
 72	
 73	    /**
 74	     * Return whether the current organism object is supposed
 75	     * to be removed from the simulation.
 76	     *
 77	     * @return A boolean value representing if the organism has been removed or not.
 78	     */
 79	    public boolean isRemoved() {
 80	        return removed;
 81	    }
 82	
 83	    /**
 84	     * Indicate that the organism is no longer alive.
 85	     */
 86	    protected void setDead()
 87	    {
 88	        alive = false;
 89	    }
 90	
 91	    /**
 92	     * Return the organism's location.
 93	     * @return The organism's location.
 94	     */
 95	    protected Location getLocation()
 96	    {
 97	        return this.location;
 98	    }
 99	
100	    /**
101	     * Place the organism at the new location in the given field.
102	     * @param newLocation The organism's new location.
103	     */
104	    protected void setLocation(Location newLocation)
105	    {
106	        if(location != null) {
107	            field.clear(location);
108	        }
109	        location = newLocation;
110	        field.place(this, newLocation);
111	    }
112	
113	    /**
114	     * Clears this organism from the field without marking it as removed.
115	     * Used by Consumable implementations (Plant, Prey) when eaten by another organism.
116	     */
117	    protected void removeFromField() {
118	        if (location != null) {
119	            field.clear(location);
120	            location = null;
121	            field = null;
122	        }
123	    }
124	
125	    /**
126	     * Return the organism's field.
127	     * @return The organism's field.
128	     */
129	    protected Field getField()
130	    {
131	        return this.field;
132	    }
133	
134	    /**
135	     * Getter method for the probability to breed of the organism.
136	     *
137	     * @return A double value representing the breeding probability.
138	     */
139	    abstract public double getBreedingProbability();
140	
141	    /**
142	     * Getter method for the maximum litter size of the organism's newborns.
143	     *
144	     * @return An integer value representing the maximum allowed litter size.
145	     */
146	    abstract public int getMaxLitterSize();
147	
148	    /**
149	     * Getter method for the maximum age of the organism.
150	     *
151	     * @return An integer value representing the maximum age.
152	     */
153	    abstract public int getMaxAge();
154	
155	    /**
156	     * Getter method for the age of breeding of the organism.
157	     *
158	     * @return A double value representing the breeding age.
159	     */
160	    abstract public int getBreedingAge();
161	
162	    /**
163	     * Called when breeding occurs for this organism.
164	     *
165	     * @return The number of births as a result of breeding.
166	     */
167	    protected int breed() {
168	        return canBreed() && rand.nextDouble() <= getBreedingProbability()
169	            ? rand.nextInt(getMaxLitterSize()) + 1 : 0;
170	    }
171	
172	    /**
173	     * Create a new instance of this organism.
174	     * @param field The field in which the spawn will reside in.
175	     * @param location The location in which the spawn will occupy.
176	     * @return A new Organism instance.
177	     */
178	    abstract protected Organism createNewOrganism(Field field, Location location);
179	
180	    /**
181	     * Check whether or not this organism is to give birth at this step.
182	     * New births will be made into free adjacent locations.
183	     * @param newOrganisms A list to return newly born organisms.
184	     */
185	    protected void giveBirth(List<Organism> newOrganisms) {
186	        Field field = getField();
187	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
188	        int births = breed();
189	        for(int b = 0; b < births && !free.isEmpty(); b++) {
190	            Location loc = free.remove(0);
191	            newOrganisms.add(createNewOrganism(field, loc));
192	        }
193	    }
194	
195	    /**
196	     * Checks all adjacent location for organisms that meet specific
197	     * breeding conditions, and returns true if it is even possible.
198	     *
199	     * @return Whether this organism can breed or not.
200	     */
201	    abstract protected boolean canBreed();
202	
203	    /**
204	     * Increase the age.
205	     * This could result in the organisms death.
206	     */
207	    protected void incrementAge()
208	    {
209	        age++;
210	
211	        if (age > getMaxAge()) {
212	            remove();
213	        }
214	    }
215	
216	    /**
217	     * Getter method for the current age of this organism.
218	     *
219	     * @return An integer value representing age.
220	     */
221	    protected int getAge() {
222	        return this.age;
223	    }
224	
225	    /**
226	     * Prevents overcrowding of dead animals by removing their corpse after
227	     * a fixed number of steps if no scavenger has consumed it.
228	     */
229	    protected void decayifDead() {
230	        this.howLongDead++;
231	        if (this.howLongDead > LIFETIME_AFTER_DEATH){
232	            remove();
233	        }
234	    }
235	}

