 11	 */
 12	public class Field
 13	{
 14	    // A random number generator for providing random locations.
 15	    private static final Random rand = Randomizer.getRandom();
 16	
 17	    // The depth and width of the field.
 18	    private final int depth;
 19	    private final int width;
 20	    // Storage for organisms — typed to avoid unchecked casts at call sites.
 21	    private final Organism[][] field;
 22	
 23	    /**
 24	     * Represent a field of the given dimensions.
 25	     * @param depth The depth of the field.
 26	     * @param width The width of the field.
 27	     */
 28	    public Field(int depth, int width)
 29	    {
 30	        this.depth = depth;
 31	        this.width = width;
 32	        field = new Organism[depth][width];
 33	    }
 34	
 35	    /**
 36	     * Empty the field.
 37	     */
 38	    public void clear()
 39	    {
 40	        for(int row = 0; row < depth; row++) {
 41	            for(int col = 0; col < width; col++) {
 42	                field[row][col] = null;
 43	            }
 44	        }
 45	    }
 46	
 47	    /**
 48	     * Clear the given location.
 49	     * @param location The location to clear.
 50	     */
 51	    public void clear(Location location)
 52	    {
 53	        field[location.getRow()][location.getCol()] = null;
 54	    }
 55	
 56	    /**
 57	     * Place an organism at the given location.
 58	     * If there is already an organism at the location it will be lost.
 59	     * @param organism The organism to be placed.
 60	     * @param row Row coordinate of the location.
 61	     * @param col Column coordinate of the location.
 62	     */
 63	    public void place(Organism organism, int row, int col)
 64	    {
 65	        place(organism, new Location(row, col));
 66	    }
 67	
 68	    /**
 69	     * Place an organism at the given location.
 70	     * If there is already an organism at the location it will be lost.
 71	     * @param organism The organism to be placed.
 72	     * @param location Where to place the organism.
 73	     */
 74	    public void place(Organism organism, Location location)
 75	    {
 76	        field[location.getRow()][location.getCol()] = organism;
 77	    }
 78	
 79	    /**
 80	     * Return the organism at the given location, if any.
 81	     * @param location Where in the field.
 82	     * @return The organism at the given location, or null if there is none.
 83	     */
 84	    public Organism getObjectAt(Location location)
 85	    {
 86	        return getObjectAt(location.getRow(), location.getCol());
 87	    }
 88	
 89	    /**
 90	     * Return the organism at the given location, if any.
 91	     * @param row The desired row.
 92	     * @param col The desired column.
 93	     * @return The organism at the given location, or null if there is none.
 94	     */
 95	    public Organism getObjectAt(int row, int col)
 96	    {
 97	        return field[row][col];
 98	    }
 99	
100	    /**
101	     * Generate a random location that is adjacent to the given location.
102	     * The returned location will be within the valid bounds of the field.
103	     * @param location The location from which to generate an adjacency.
104	     * @return A valid location within the grid area.
105	     */
106	    public Location randomAdjacentLocation(Location location)
107	    {
108	        List<Location> adjacent = adjacentLocations(location);
109	        return adjacent.get(0);
110	    }
111	
112	    /**
113	     * Get a shuffled list of the free adjacent locations.
114	     * @param location Get locations adjacent to this.
115	     * @return A list of free adjacent locations.
116	     */
117	    public List<Location> getFreeAdjacentLocations(Location location)
118	    {
119	        List<Location> free = new LinkedList<>();
120	        for(Location next : adjacentLocations(location)) {
121	            if(getObjectAt(next) == null) {
122	                free.add(next);
123	            }
124	        }
125	        return free;
126	    }
127	
128	    /**
129	     * Try to find a free location that is adjacent to the given location.
130	     * @param location The location from which to generate an adjacency.
131	     * @return A valid free location, or null if none exists.
132	     */
133	    public Location freeAdjacentLocation(Location location)
134	    {
135	        List<Location> free = getFreeAdjacentLocations(location);
136	        return free.isEmpty() ? null : free.get(0);
137	    }
138	
139	    /**
140	     * Return a shuffled list of locations adjacent to the given one.
141	     * The list will not include the location itself.
142	     * All locations will lie within the grid.
143	     * @param location The location from which to generate adjacencies.
144	     * @return A list of locations adjacent to that given.
145	     */
146	    public List<Location> adjacentLocations(Location location)
147	    {
148	        List<Location> locations = new LinkedList<>();
149	        int row = location.getRow();
150	        int col = location.getCol();
151	        for(int roffset = -1; roffset <= 1; roffset++) {
152	            int nextRow = row + roffset;
153	            if(nextRow >= 0 && nextRow < depth) {
154	                for(int coffset = -1; coffset <= 1; coffset++) {
155	                    int nextCol = col + coffset;
156	                    if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
157	                        locations.add(new Location(nextRow, nextCol));
158	                    }
159	                }
160	            }
161	        }
162	        Collections.shuffle(locations, rand);
163	        return locations;
164	    }
165	
166	    /**
167	     * Return the depth of the field.
168	     */
169	    public int getDepth() { return depth; }
170	
171	    /**
172	     * Return the width of the field.
173	     */
174	    public int getWidth() { return width; }
175	}

