  1	import javax.swing.*;
  2	import java.awt.*;
  3	import java.util.LinkedHashMap;
  4	import java.util.Map;
  5	
  6	/**
  7	 * A graphical view of the simulation grid.
  8	 * The view displays a colored rectangle for each location 
  9	 * representing its contents. It uses a default background color.
 10	 * Colors for each type of species can be defined using the
 11	 * setColor method.
 12	 *
 13	 * @version 2022.03.02
 14	 */
 15	public class SimulatorView extends JFrame
 16	{
 17	    // Colors used for empty locations.
 18	    private static final Color EMPTY_COLOR = Color.white;
 19	
 20	    // Color used for objects that have no defined color.
 21	    private static final Color UNKNOWN_COLOR = Color.gray;
 22	
 23	    private static final String STEP_PREFIX        = "Step: ";
 24	    private static final String TIME_DAY_PREFIX    = "Day: ";
 25	    private static final String TIME_HOUR_PREFIX   = "Hour: ";
 26	    private static final String TIME_OF_DAY_PREFIX = "Time: ";
 27	    private static final String POPULATION_PREFIX  = "Population: ";
 28	    private static final String WEATHER_PREFIX     = "Weather: ";
 29	
 30	    private JLabel stepLabel, population, timeLabel, environmentLabel;
 31	    private FieldView fieldView;
 32	    
 33	    // A map for storing colors for participants in the simulation
 34	    private Map<Class<?>, Color> colors;
 35	    // A statistics object computing and storing simulation information
 36	    private FieldStats stats;
 37	
 38	    /**
 39	     * Create a view of the given width and height.
 40	     * @param height The simulation's height.
 41	     * @param width  The simulation's width.
 42	     */
 43	    public SimulatorView(int height, int width)
 44	    {
 45	        stats = new FieldStats();
 46	        colors = new LinkedHashMap<Class<?>, Color>();
 47	
 48	        setTitle("Predator Prey Simulation");
 49	        stepLabel = new JLabel(STEP_PREFIX, JLabel.CENTER);
 50	        timeLabel = new JLabel(" ", JLabel.CENTER);
 51	        environmentLabel = new JLabel(" ", JLabel.CENTER);
 52	        population = new JLabel(POPULATION_PREFIX, JLabel.CENTER);
 53	        
 54	        setLocation(100, 50);
 55	        
 56	        fieldView = new FieldView(height, width);
 57	
 58	        Container contents = getContentPane();
 59	        
 60	        JPanel infoPane = new JPanel(new BorderLayout());
 61	            infoPane.add(stepLabel, BorderLayout.WEST);
 62	            infoPane.add(timeLabel, BorderLayout.EAST);
 63	            infoPane.add(environmentLabel, BorderLayout.CENTER);
 64	
 65	
 66	        contents.add(infoPane, BorderLayout.NORTH);
 67	        contents.add(fieldView, BorderLayout.CENTER);
 68	        contents.add(population, BorderLayout.SOUTH);
 69	        pack();
 70	        setVisible(true);
 71	    }
 72	    
 73	    /**
 74	     * Define a color to be used for a given class of animal.
 75	     * @param animalClass The animal's Class object.
 76	     * @param color The color to be used for the given class.
 77	     */
 78	    public void setColor(Class<?> animalClass, Color color)
 79	    {
 80	        colors.put(animalClass, color);
 81	    }
 82	
 83	    /**
 84	     * @return The color to be used for a given class of animal.
 85	     */
 86	    private Color getColor(Class<?> animalClass)
 87	    {
 88	        Color col = colors.get(animalClass);
 89	        if(col == null) {
 90	            // no color defined for this class
 91	            return UNKNOWN_COLOR;
 92	        }
 93	        else {
 94	            return col;
 95	        }
 96	    }
 97	
 98	    /**
 99	     * Show the current status of the field.
100	     * @param step Which iteration step it is.
101	     * @param field The field whose status is to be displayed.
102	     */
103	    public void showStatus(int step, Field field)
104	    {
105	        if(!isVisible()) {
106	            setVisible(true);
107	        }
108	        stepLabel.setText(STEP_PREFIX + step);
109	        stats.reset();
110	        
111	        fieldView.preparePaint();
112	
113	        for(int row = 0; row < field.getDepth(); row++) {
114	            for(int col = 0; col < field.getWidth(); col++) {
115	                Organism organism = field.getObjectAt(row, col);
116	                if(organism != null) {
117	                    stats.incrementCount(organism.getClass());
118	                    fieldView.drawMark(col, row, getColor(organism.getClass()));
119	                }
120	                else {
121	                    fieldView.drawMark(col, row, EMPTY_COLOR);
122	                }
123	            }
124	        }
125	        stats.countFinished();
126	
127	        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
128	        fieldView.repaint();
129	    }
130	
131	    /**
132	     * Determine whether the simulation should continue to run.
133	     * @return true If there is more than one species alive.
134	     */
135	    public boolean isViable(Field field)
136	    {
137	        return stats.isViable(field);
138	    }
139	
140	    public void updateTimeLabel(int day, int hour){
141	        timeLabel.setText(TIME_DAY_PREFIX + (day) + " " + TIME_HOUR_PREFIX + (hour));
142	    }
143	
144	    public void updateEnvironmentLabel(Weather weather, TimeOfDay time) {
145	        environmentLabel.setText(WEATHER_PREFIX + weather.getType().toString() + " " + TIME_OF_DAY_PREFIX + time);
146	    }
147	    
148	    /**
149	     * Provide a graphical view of a rectangular field. This is 
150	     * a nested class (a class defined inside a class) which
151	     * defines a custom component for the user interface. This
152	     * component displays the field.
153	     * This is rather advanced GUI stuff - you can ignore this 
154	     * for your project if you like.
155	     */
156	    private class FieldView extends JPanel
157	    {
158	        private final int GRID_VIEW_SCALING_FACTOR = 6;
159	
160	        private int gridWidth, gridHeight;
161	        private int xScale, yScale;
162	        Dimension size;
163	        private Graphics g;
164	        private Image fieldImage;
165	
166	        /**
167	         * Create a new FieldView component.
168	         */
169	        public FieldView(int height, int width)
170	        {
171	            gridHeight = height;
172	            gridWidth = width;
173	            size = new Dimension(0, 0);
174	        }
175	
176	        /**
177	         * Tell the GUI manager how big we would like to be.
178	         */
179	        public Dimension getPreferredSize()
180	        {
181	            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
182	                                 gridHeight * GRID_VIEW_SCALING_FACTOR);
183	        }
184	
185	        /**
186	         * Prepare for a new round of painting. Since the component
187	         * may be resized, compute the scaling factor again.
188	         */
189	        public void preparePaint()
190	        {
191	            if(! size.equals(getSize())) {  // if the size has changed...
192	                size = getSize();
193	                fieldImage = fieldView.createImage(size.width, size.height);
194	                g = fieldImage.getGraphics();
195	
196	                xScale = size.width / gridWidth;
197	                if(xScale < 1) {
198	                    xScale = GRID_VIEW_SCALING_FACTOR;
199	                }
200	                yScale = size.height / gridHeight;
201	                if(yScale < 1) {
202	                    yScale = GRID_VIEW_SCALING_FACTOR;
203	                }
204	            }
205	        }
206	        
207	        /**
208	         * Paint on grid location on this field in a given color.
209	         */
210	        public void drawMark(int x, int y, Color color)
211	        {
212	            g.setColor(color);
213	            g.fillRect(x * xScale, y * yScale, xScale-1, yScale-1);
214	        }
215	
216	        /**
217	         * The field view component needs to be redisplayed. Copy the
218	         * internal image to screen.
219	         */
220	        public void paintComponent(Graphics g)
221	        {
222	            if(fieldImage != null) {
223	                Dimension currentSize = getSize();
224	                if(size.equals(currentSize)) {
225	                    g.drawImage(fieldImage, 0, 0, null);
226	                }
227	                else {
228	                    // Rescale the previous image.
229	                    g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
230	                }
231	            }
232	        }
233	    }
234	}

